def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    while b:
        a, b = b, a % b
    return abs(a)

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    # Start from n-1 and go downwards to find the largest divisor less than n
    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i
    return 1  # This line is technically unreachable for n > 1, but included for completeness

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    flipped = []
    for char in string:
        if char.islower():
            flipped.append(char.upper())
        elif char.isupper():
            flipped.append(char.lower())
        else:
            flipped.append(char)
    return ''.join(flipped)

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

import math

def triangle_area(a, b, c):
    # Check if the three sides can form a valid triangle
    if a + b > c and a + c > b and b + c > a:
        # Calculate semi-perimeter
        s = (a + b + c) / 2
        # Calculate area using Heron's formula
        area = math.sqrt(s * (s - a) * (s - b) * (s - c))
        # Round to 2 decimal places and return
        return round(area, 2)
    else:
        # Invalid triangle
        return -1

def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers, False otherwise."""
    # Helper to check primality for numbers < 100
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find three prime factors (could be same? Problem implies distinct? Example uses distinct.
    # Usually "multiplication of 3 prime numbers" means three primes (not necessarily distinct) whose product equals a.
    # Since a < 100, we can brute force all combinations of three primes (with repetition allowed) whose product equals a.
    primes = [p for p in range(2, a) if is_prime(p)]

    # Try all combinations of three primes (order doesn't matter)
    for i in range(len(primes)):
        for j in range(i, len(primes)):  # allow same index to permit repetition
            for k in range(j, len(primes)):
                product = primes[i] * primes[j] * primes[k]
                if product == a:
                    return True
                if product > a:
                    break
    return False

def hex_key(num):
    """
    Counts the number of hexadecimal digits in the input string that are prime numbers.
    Prime hexadecimal digits are: 2, 3, 5, 7, B (11), D (13).
    """
    # Set of prime hexadecimal digits (as characters)
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for digit in num:
        if digit in prime_hex_digits:
            count += 1
    return count

def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Examples:
    For lst = [0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3] the output should be 10
    For lst = [1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1] the output should be 25
    For lst = [1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3] the output should be 13
    For lst = [0,724,32,71,99,32,6,0,5,91,83,0,5,6] the output should be 11
    For lst = [0,81,12,3,1,21] the output should be 3
    For lst = [0,8,1,2,1,7] the output should be 7
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    max_prime = -1
    for num in lst:
        if is_prime(num) and num > max_prime:
            max_prime = num

    # sum of digits of max_prime
    return sum(int(d) for d in str(max_prime))

def check_dict_case(dict):
    """
    Given a dictionary, return True if all keys are strings in lower 
    case or all keys are strings in upper case, else return False.
    The function should return False is the given dictionary is empty.
    Examples:
    check_dict_case({"a":"apple", "b":"banana"}) should return True.
    check_dict_case({"a":"apple", "A":"banana", "B":"banana"}) should return False.
    check_dict_case({"a":"apple", 8:"banana", "a":"apple"}) should return False.
    check_dict_case({"Name":"John", "Age":"36", "City":"Houston"}) should return False.
    check_dict_case({"STATE":"NC", "ZIP":"12345" }) should return True.
    """
    if not dict:
        return False

    # Determine the case type based on the first string key encountered
    case_type = None
    for key in dict.keys():
        if isinstance(key, str):
            if case_type is None:
                # Set case_type based on the first string key
                if key.islower():
                    case_type = 'lower'
                elif key.isupper():
                    case_type = 'upper'
                else:
                    # If the first string key is not all lower or all upper, return False
                    return False
            else:
                # Check subsequent string keys against the established case_type
                if case_type == 'lower' and not key.islower():
                    return False
                if case_type == 'upper' and not key.isupper():
                    return False
        else:
            # If a key is not a string, return False
            return False

    # If we have at least one string key and all checks passed, return True
    return True

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)
    return primes

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()

    # Count occurrences of each letter
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(counts.values())

    # Build result dictionary with all letters that have the maximum count
    result = {letter: count for letter, count in counts.items() if count == max_count}

    return result

def split_words(txt):
    # Check if there is any whitespace in the string
    if any(char.isspace() for char in txt):
        # Split on whitespace
        return txt.split()
    # Check if there is any comma in the string
    elif ',' in txt:
        # Split on commas
        return txt.split(',')
    else:
        # Count lower-case letters with odd order in the alphabet
        # ord('a') = 0, ord('b') = 1, ... ord('z') = 25
        count = 0
        for char in txt:
            if 'a' <= char <= 'z':
                # ord(char) - ord('a') gives the position (0-25)
                if (ord(char) - ord('a')) % 2 == 1:
                    count += 1
        return count

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_number(x):
        if isinstance(x, (int, float)):
            return x
        if isinstance(x, str):
            # Replace comma with dot if present
            if ',' in x:
                x = x.replace(',', '.')
            try:
                return float(x)
            except ValueError:
                # If conversion fails, return None or raise? According to problem, assume valid input
                return float('nan')
        return None

    a_num = to_number(a)
    b_num = to_number(b)

    # If either conversion failed (should not happen per problem constraints), handle gracefully
    if a_num is None or b_num is None:
        return None

    if a_num > b_num:
        return a
    elif b_num > a_num:
        return b
    else:
        return None

def cycpattern_check(a, b):
    # If b is longer than a, it cannot be a substring or rotation
    if len(b) > len(a):
        return False

    # Check if b is a substring of a
    if b in a:
        return True

    # Generate all rotations of b and check if any rotation is a substring of a
    rotations = [b[i:] + b[:i] for i in range(len(b))]
    for rot in rotations:
        if rot in a:
            return True

    return False

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    # Convert to absolute value to handle negative numbers
    num = abs(num)
    even = 0
    odd = 0
    # Handle the case num == 0 separately
    if num == 0:
        even = 1
    else:
        while num > 0:
            digit = num % 10
            if digit % 2 == 0:
                even += 1
            else:
                odd += 1
            num //= 10
    return (even, odd)

def solve(s):
    """You are given a string s.
    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    # Check if there is at least one letter in the string
    has_letter = any(ch.isalpha() for ch in s)

    if not has_letter:
        # If no letters, reverse the string
        return s[::-1]
    else:
        # Otherwise, swap case for letters, leave others unchanged
        result = []
        for ch in s:
            if ch.isalpha():
                # Swap case: lower -> upper, upper -> lower
                result.append(ch.swapcase())
            else:
                result.append(ch)
        return ''.join(result)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
